INTERCEPT = [0.003678003607342, -0.13029750890981784, -0.13479731580002588, -0.389500730292944, -0.32858257525999446, 0.18845504414984324, -0.0057028916187115836, 0.17640566297805124, 0.32854696585549237, 0.29179534529084833]

TERM_INDEX = {term: i for i, term in enumerate(TERMS)}


def features(text: str) -> dict[int, float]:
    """Sparse TF-IDF row as {column: value} (unigrams and bigrams)."""
    tokens = TOKEN_RE.findall(text.lower())
    counts: dict[str, int] = {}
    for tok in tokens:
        counts[tok] = counts.get(tok, 0) + 1
    for a, b in zip(tokens, tokens[1:]):
        pair = a + " " + b
        counts[pair] = counts.get(pair, 0) + 1
    row: dict[int, float] = {}
    for term, count in counts.items():
        idx = TERM_INDEX.get(term)
        if idx is None:
            continue
        row[idx] = (1.0 + math.log(count)) * IDF[idx]
    norm = math.sqrt(sum(v * v for v in row.values()))
    if norm > 0.0:
        for idx in row:
            row[idx] /= norm
    return row


def predict(texts: list[str]) -> list[str]:
    out: list[str] = []
    for text in texts:
        row = features(text)
        best_k = 0
        best_s = -math.inf
        for k in range(10):
            coef_k = COEF[k]
            score = INTERCEPT[k]
            for idx, value in row.items():
                score += value * coef_k[idx]
            if score > best_s:
                best_s = score
                best_k = k
        out.append(CLASSES[best_k])
    return out


def main() -> int:
    argv = sys.argv[1:]
    input_name = "test-input.json"
    output_name = "predictions.json"
    i = 0
    while i < len(argv):          # tolerate the documented optional flags
        if argv[i] == "--input" and i + 1 < len(argv):
            input_name = argv[i + 1]
            i += 2
        elif argv[i] == "--output" and i + 1 < len(argv):
            output_name = argv[i + 1]
            i += 2
        else:
            i += 1
    try:
        with open(input_name, encoding="utf-8") as fh:
            records = json.load(fh)
    except OSError as exc:
        print(f"input file not found: {input_name} ({exc})", file=sys.stderr)
        return 2
    ids = [r["id"] for r in records]
    texts = [r.get("text", "") or "" for r in records]
    labels = predict(texts)
    predictions = [{"id": rid, "label": label} for rid, label in zip(ids, labels)]
    with open(output_name, "w", encoding="utf-8") as fh:
        json.dump(predictions, fh, indent=2, ensure_ascii=False)
        fh.write("\n")
    print(f"wrote {len(predictions)} predictions to {output_name}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
